function pathDist(x,z){let best=1e9;const routes=[[[-57,83],[-57,48],[-20,43],[15,40],[49,32]],[[49,32],[36,7],[35,-22],[16,-29]],[[16,-54],[-20,-48],[-66,-57]],[[-57,48],[-72,15],[-72,-18],[-66,-36]]];for(const points of routes)for(let i=1;i<points.length;i++){const [a,b]=[points[i-1],points[i]],dx=b[0]-a[0],dz=b[1]-a[1],t=Math.max(0,Math.min(1,((x-a[0])*dx+(z-a[1])*dz)/(dx*dx+dz*dz)));best=Math.min(best,Math.hypot(x-a[0]-dx*t,z-a[1]-dz*t))}return best}
